export function createResilientFetch({ fetch, sleep, random = Math.random, maxAttempts = 4, baseDelayMs = 200, maxDelayMs = 5000 }) {
  return async function rfetch(url, options = {}) {
    const method = (options.method || 'GET').toUpperCase();
    if (!['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE'].includes(method) && (!options.headers || !options.headers['Idempotency-Key'])) {
      throw new Error('Method not allowed');
    }

    let attempt = 0;
    let lastError = null;

    while (attempt < maxAttempts) {
      attempt++;
      try {
        const response = await fetch(url, options);
        if (response.ok) {
          return response;
        }
        if ([408, 429, 500, 502, 503, 504].includes(response.status)) {
          const retryAfter = response.headers.get('Retry-After');
          if (retryAfter && !isNaN(retryAfter) && retryAfter >= 0) {
            const delay = retryAfter * 1000;
            if (delay > maxDelayMs) {
              return response;
            }
            await sleep(delay, options.signal);
          } else {
            const delay = Math.floor(random() * Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)));
            await sleep(delay, options.signal);
          }
        } else {
          return response;
        }
      } catch (error) {
        if (error.name === 'AbortError') {
          throw error;
        }
        lastError = error;
        if (attempt === maxAttempts) {
          throw lastError;
        }
        const delay = Math.floor(random() * Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)));
        await sleep(delay, options.signal);
      }
    }
  };
}
